def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for i, operation in enumerate(ops):
        tokens = operation.split()
        if not tokens:
            rejected.append(i)
            continue

        verb = tokens[0]
        try:
            if verb == "open" and len(tokens) == 3:
                account, raw_amount = tokens[1], tokens[2]
                if not raw_amount.isascii() or not raw_amount.isdigit():
                    raise ValueError
                amount = int(raw_amount)
                if account in balances:
                    raise ValueError
                balances[account] = amount
                history.append(("open", account))

            elif verb == "deposit" and len(tokens) == 3:
                account, raw_amount = tokens[1], tokens[2]
                if not raw_amount.isascii() or not raw_amount.isdigit():
                    raise ValueError
                amount = int(raw_amount)
                if amount <= 0 or account not in balances:
                    raise ValueError
                balances[account] += amount
                history.append(("balance", account, -amount))

            elif verb == "withdraw" and len(tokens) == 3:
                account, raw_amount = tokens[1], tokens[2]
                if not raw_amount.isascii() or not raw_amount.isdigit():
                    raise ValueError
                amount = int(raw_amount)
                if amount <= 0 or account not in balances or account in frozen or balances[account] < amount:
                    raise ValueError
                balances[account] -= amount
                history.append(("balance", account, amount))

            elif verb == "transfer" and len(tokens) == 4:
                source, target, raw_amount = tokens[1], tokens[2], tokens[3]
                if not raw_amount.isascii() or not raw_amount.isdigit():
                    raise ValueError
                amount = int(raw_amount)
                if (amount <= 0 or source == target or source not in balances or
                        target not in balances or source in frozen or balances[source] < amount):
                    raise ValueError
                balances[source] -= amount
                balances[target] += amount
                history.append(("transfer", source, target, amount))

            elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
                account = tokens[1]
                if account not in balances:
                    raise ValueError
                if verb == "freeze":
                    if account in frozen:
                        raise ValueError
                    frozen.add(account)
                    history.append(("freeze", account))
                else:
                    if account not in frozen:
                        raise ValueError
                    frozen.remove(account)
                    history.append(("unfreeze", account))

            elif verb == "undo" and len(tokens) == 1:
                if not history:
                    raise ValueError
                action = history.pop()
                kind = action[0]
                if kind == "open":
                    account = action[1]
                    del balances[account]
                    frozen.discard(account)
                elif kind == "balance":
                    _, account, delta = action
                    balances[account] += delta
                elif kind == "transfer":
                    _, source, target, amount = action
                    balances[source] += amount
                    balances[target] -= amount
                elif kind == "freeze":
                    frozen.remove(action[1])
                elif kind == "unfreeze":
                    frozen.add(action[1])
            else:
                raise ValueError
        except ValueError:
            rejected.append(i)

    return balances, rejected
